// WOFF ID
const woffId = "0sEo_G5hZf8ABtEMZv_MnA";

/**
* Alert the user if WOFF is opened in an external browser and unavailable buttons are tapped
*/
const sendAlertIfNotInClient = () => {
    alert('This button is unavailable as WOFF is currently opened in an external browser.');
}

/**
* Display data generated by invoking WOFF methods
*/
const displayWoffData = () => {
    document.getElementById('browserLanguage').textContent = woff.getLanguage();
    document.getElementById('sdkVersion').textContent = woff.getVersion();
    document.getElementById('lineWorksVersion').textContent = woff.getWorksVersion();
    document.getElementById('isInClient').textContent = woff.isInClient();//WOFF アプリが LINE WORKS 内の WOFF ブラウザで実行されていることを確認
    document.getElementById('isLoggedIn').textContent = woff.isLoggedIn();
    document.getElementById('deviceOS').textContent = woff.getOS();

    var context = woff.getContext();
    //console.log("context:",context)
    //console.log("context.viewType:",context.viewType)// "external"
    //console.log("context.endpointUrl:",context.endpointUrl)//https://stunning-space-enigma-xrx4ww7jppjrhvg7x-9000.app.github.dev/
    //console.log("context.clientId:",context.clientId)//DICH4bfkjcJBnehVROv9
    //console.log("context.clientType:",context.clientType)//MOBILE＿APP
    //console.log("context.channelId:",context.channelId)//なし？
    //console.log("context.availability:",context.availability)//ScanQR　だけなのはなぜ？→「WOFF アプリ専用のネイティブ拡張機能」が現時点で scanQR（QRコードスキャン）を中心として用意されているため
    //console.log("context.appApiId:",context.appApiId)  //なし？→Developer Console で「App API」との紐付け設定を行っていない（または使用していない）ため
    //console.log("context.serviceCode:",context.serviceCode) //message　ほかには？そもそもserviceCodeとは？→「どのサービス機能（モジュール）の画面から WOFF アプリが呼び出されたか」 を特定するための識別コード
    //"message" (または "talk")： トーク（チャット）画面から起動
    //"board"： 掲示板（Board）から起動
    //"calendar"： カレンダーから起動
    //"drive"： マイドライブ / 共有ドライブから起動
    //"" (空文字)： サービス外（ブラウザでの直接アクセスや外部ウィンドウ展開時）
    //console.log("context.permanentLinkPattern:",context.permanentLinkPattern) //concat ほかには？
    //"concat"（標準）： WOFF URL に付与されたパラメータ（?key=value）を、設定された endpointUrl の末尾に単純結合（Concatenate）して引き継ぐ設定。
    //"replace"： パラメータの結合ではなく、特定の変数部分をパラメータ値で置き換える設定。
    //"none" (または未定義)： URL パラメータの引き継ぎを行わない設定。
    document.getElementById('viewType').textContent = context.viewType;
    document.getElementById('endpointUrl').textContent = context.endpointUrl;
    document.getElementById('clientId').textContent = context.clientId;
    document.getElementById('clientType').textContent = context.clientType;
    document.getElementById('channelId').textContent = context.channelId;

    const claims = woff.getDecodedIDToken();
    console.log("woff.getDecodedIDToken() 呼び出し結果:", claims);
    if (claims) {
        console.log("claims.sub", claims.sub);
        console.log("claims.name", claims.name);
        console.log("claims.email", claims.email);
        console.log("claims.iss", claims.iss);
        console.log("claims.aud", claims.aud);
        console.log("claims.exp", claims.exp);
        console.log("claims.iat", claims.iat);
        console.log("claims.auth_time", claims.auth_time);
        console.log("claims.nonce", claims.nonce);
        console.log("claims.picture", claims.picture);
        console.log("claims.domainId", claims.domainId);
    }


    if (woff.isInClient()) {
        document.getElementById('isInClientMessage').textContent = 'Opening the app in the in-app browser of LINE WORKS.';
    } else {
        document.getElementById('isInClientMessage').textContent = 'Opening the app in an external browser.';
    }
}

/**
* Register event handlers for the buttons displayed in the app
*/
const registerButtonHandlers = () => {
    // openWindow call
    document.getElementById('openWindowButton').addEventListener('click', () => {
        console.log("open window");
        woff.openWindow({
            url: 'https://line.worksmobile.com/',
            external: true
        });
    });

    // closeWindow call
    document.getElementById('closeWindowButton').addEventListener('click', () => {
        if (!woff.isInClient()) {
            sendAlertIfNotInClient();
        } else {
            console.log("close window");
            woff.closeWindow();
        }
    });

    // sendMessage call
    document.getElementById('sendMessageButton').addEventListener('click', () => {
        if (!woff.isInClient()) {
            sendAlertIfNotInClient();
        } else {
            let msg = document.getElementById('sendMessageText').value
            woff.sendMessage({
                'content': msg
            }).then(() => {
                console.log("message sent: " + msg)
                window.alert('Message sent');
            }).catch((error) => {
                console.error(error)
                window.alert('Error sending message: ' + error);
            });
        }
    });

    // sendFlexMessage call
    document.getElementById('sendFlexMessageButton').addEventListener('click', () => {
        if (!woff.isInClient()) {
            sendAlertIfNotInClient();
        } else {
            let msg = {
                "type": "flex",
                "altText": "this is a flexible template",
                "contents": {
                  "type": "bubble",
                  "body": {
                    "type": "box",
                    "layout": "vertical",
                    "contents": [
                      {
                        "type": "text",
                        "text": "hello"
                      },
                      {
                        "type": "text",
                        "text": "world"
                      }
                    ]
                  }
                }
            }

            woff.sendFlexMessage({
                flex: msg
            }).then(() => {
                console.log("flex message sent: " + msg)
                window.alert('Message sent');
            }).catch((error) => {
                console.error(error)
                window.alert('Error sending message: ' + error);
            });
        }
    });

    // get access token
    document.getElementById('getAccessToken').addEventListener('click', () => {
        if (!woff.isLoggedIn() && !woff.isInClient()) {
            alert('To get an access token, you need to be logged in. Please tap the "login" button below and try again.');
        } else {
            console.log("Get access token");
            const accessToken = woff.getAccessToken();
            document.getElementById('accessTokenField').textContent = accessToken;
        }
    });

    // get profile call
    document.getElementById('getProfileButton').addEventListener('click', () => {
        console.log("Get profile");
        woff.getProfile().then((profile) => {
            // ★ .then() の中で取得した profile をログ出力する
            console.log("woff.getProfile():", profile);
            console.log("profile.displayName:", profile.displayName);
            console.log("profile.worksLanguage:", profile.worksLanguage);
            console.log("profile.userId:", profile.userId);
            console.log("profile.domainId:", profile.domainId);
            document.getElementById('domainIdField').textContent = profile.domainId;
            document.getElementById('userIdProfileField').textContent = profile.userId;
            document.getElementById('displayNameField').textContent = profile.displayName;
        }).catch((error) => {
            console.error(error)
            window.alert('Error getting profile: ' + error);
        });
    });

    // get channel Id
    document.getElementById('getChannelIdButton').addEventListener('click', () => {
        console.log("Get channel id");
        woff.getChannelId().then((channelId) => {
            console.log(channelId);
            document.getElementById('channelIdField').textContent = channelId;
        }).catch((error) => {
            console.error(error)
            window.alert('Error getting channel Id: ' + error);
        });
    });

    // login call, only when external browser is used
    document.getElementById('woffLoginButton').addEventListener('click', () => {
        if (!woff.isLoggedIn()) {
            console.log("Login");
            // set `redirectUri` to redirect the user to a URL other than the front page of your WOFF app.
            woff.login();
        }
    });

    // logout call only when external browse
    document.getElementById('woffLogoutButton').addEventListener('click', () => {
        if (woff.isLoggedIn()) {
            woff.logout();
            window.location.reload();
        }
    });

    // scan QR
    document.getElementById('scanQrButton').addEventListener('click', () => {
        console.log("Scan QR");
        woff.scanQR().then((result) => {
            document.getElementById('scanQrResult').textContent = result.value;
        }).catch((error) => {
            console.error(error)
            window.alert('Error scanning QR: ' + error);
        });
    });
}

/**
 * Initialize the app by calling functions handling individual app components
 */
const initializeApp = () => {
    displayWoffData();
    registerButtonHandlers();

    // check if the user is logged in/out, and disable inappropriate button
    if (woff.isLoggedIn()) {
        document.getElementById('woffLoginButton').disabled = true;
        document.getElementById('woffLogoutButton').disabled = false;
    } else {
        document.getElementById('woffLoginButton').disabled = false;
        document.getElementById('woffLogoutButton').disabled = true;
    }
}

/**
* Initialize WOFF
* @param {string} myWoffId The WOFF ID of the selected element
*/
const initializeWoff = (myWoffId) => {
    woff.init({
            woffId: myWoffId,
            // 外部ブラウザアクセス時のログイン後リダイレクト先を指定したい場合
            redirectUri: "https://stunning-space-enigma-xrx4ww7jppjrhvg7x-9000.app.github.dev/",
            scope: "openid profile"
        })
        .then(() => {
            // successCallback
            // start to use WOFF's api      
            initializeApp();
        })
        .catch((err) => {
            // errorCallback
            console.error(err)
            document.getElementById("woffInitErrorMessage").hidden = false;
        });
}

// On load
window.addEventListener('load', () => {
    console.log('WOFF_ID: ' + woffId);
    initializeWoff(woffId);
});
